int qrx_aura_live_scheduler_release(QrxAuraAdmission*a,QrxAuraRuntimeBinding*b,size_t n){if(!a||!b||!a->active)return -1;int rc=0;for(uint32_t i=0;i<a->pod_count;i++){QrxAuraRuntimeBinding*rb=binding(b,n,a->pods[i].pod_id,a->pods[i].provider_id);if(!rb||qrx_resource_provider_runtime_release(rb->provider_runtime,0,a->pods[i].model_cache_bytes,a->pods[i].compute_threads,a->pods[i].network_egress_mbps))rc=-2;}a->active=0;return rc;}

int qrx_aura_dispatch_result_commitment(const QrxAuraDispatchResult*r,char out[65]){if(!r||r->version!=QRX_AURA_LIVE_DISPATCH_VERSION||!hex64(r->admission_commitment)||!hex64(r->model_commitment)||!r->runtime_id[0]||!r->provider_id[0]||!r->pod_id[0]||!r->pod_count||!hex64(r->output_commitment))return -1;EVP_MD_CTX*x=NULL;if(hash_begin(&x,"QRX/AURA/RUNTIME-DISPATCH-RESULT/V1"))return -2;int ok=!h_s(x,r->admission_commitment)&&!h_s(x,r->model_commitment)&&!h_s(x,r->runtime_id)&&!h_s(x,r->provider_id)&&!h_s(x,r->pod_id)&&!h_u32(x,r->pod_count)&&!h_u64(x,r->output_bytes)&&!h_s(x,r->output_commitment);if(!ok){EVP_MD_CTX_free(x);return -2;}return hash_end(x,out);}
int qrx_aura_runtime_dispatch_execute(const QrxAuraAdmission*a,const QrxComputeJobNode*node,QrxAuraRuntimeBinding*b,size_t bn,const void*in,size_t in_n,void*out,size_t outcap,size_t*outn,QrxAuraDistributedDispatchFn remote,void*ctx,QrxAuraDispatchResult*r){if(!a||!node||!b||!outn||!r||!a->active||node->node_id!=a->node_id||strcmp(node->runtime_id,a->route.runtime_id)||strcmp(node->model_id,a->route.model_id)||strcmp(node->model_version,a->route.model_version))return -1;char ac[65];if(qrx_aura_admission_commitment(a,ac)||strcmp(ac,a->admission_commitment))return -2;*outn=0;int rc=-1;QrxAuraRuntimeBinding*primary=binding(b,bn,a->pods[0].pod_id,a->pods[0].provider_id);if(!primary)return -3;if(a->pod_count==1&&primary->local){QrxMoeWorkerRequirement wr;memset(&wr,0,sizeof(wr));wr.version=QRX_MOE_DISCOVERY_VERSION;wr.backend=primary->device.backend;wr.required_device_memory_bytes=node->min_memory_bytes;wr.requested_batch_items=1;wr.required_kernel_features=primary->adapter.kernel_mask;rc=qrx_moe_worker_adapter_execute(&primary->adapter,&primary->device,&wr,in,in_n,out,outcap,outn);}else{if(!remote)return -4;rc=remote(ctx,a,node,in,in_n,out,outcap,outn);}if(rc)return -5;memset(r,0,sizeof(*r));r->version=QRX_AURA_LIVE_DISPATCH_VERSION;snprintf(r->admission_commitment,65,"%s",a->admission_commitment);snprintf(r->model_commitment,65,"%s",a->model_commitment);snprintf(r->runtime_id,sizeof(r->runtime_id),"%s",a->route.runtime_id);snprintf(r->provider_id,sizeof(r->provider_id),"%s",a->pods[0].provider_id);snprintf(r->pod_id,sizeof(r->pod_id),"%s",a->pods[0].pod_id);r->pod_count=a->pod_count;r->output_bytes=*outn;if(content_commitment(out,*outn,r->output_commitment))return -6;return qrx_aura_dispatch_result_commitment(r,r->result_commitment);}
int qrx_aura_dispatch_build_pouc_receipt(const QrxAuraAdmission*a,const QrxAuraDispatchResult*r,const char input[65],uint64_t atoms,uint64_t st,uint64_t co,uint32_t mode,QrxPoucReceipt*out){if(!a||!r||!input||!out||!hex64(input)||!a->active||strcmp(a->admission_commitment,r->admission_commitment)||!hex64(r->result_commitment))return -1;memset(out,0,sizeof(*out));out->version=QRX_POUC_VERSION;snprintf(out->graph_commitment,65,"%s",a->graph_commitment);out->node_id=a->node_id;snprintf(out->provider_id,sizeof(out->provider_id),"%s",r->provider_id);snprintf(out->input_commitment,65,"%s",input);snprintf(out->model_commitment,65,"%s",a->model_commitment);snprintf(out->runtime_id,sizeof(out->runtime_id),"%s",r->runtime_id);snprintf(out->execution_params_commitment,65,"%s",a->admission_commitment);snprintf(out->result_commitment,65,"%s",r->result_commitment);out->verified_compute_atoms=atoms;out->started_height=st;out->completed_height=co;out->verification_mode=mode;return qrx_pouc_receipt_validate(out);}
